"use client";

import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { Layers3, Search, Ungroup, X } from "lucide-react";
import type { CardEditorLiveModel } from "@/components/fusion/card/card-editor-live";
import type { CreativeCompositionNode } from "@/lib/fusion/creative-studio/composition";
import { compositionChildren, hasCompositionParentAuthority } from "@/lib/fusion/card/composition-parent-authority";
import { cn } from "@/lib/utils";
import { MediaPicker } from "@/components/media/media-picker";
import { applyStudioSurfaceParameters, applyStudioSurfaceTreatment, readStudioSurfaceState, STUDIO_SURFACE_TREATMENTS } from "@/lib/fusion/creative-studio/platform/surface-capability";
import { StudioPrecisionControl } from "./studio-precision-control";
import { ordinaryModuleKind, resolveOrdinaryModuleCapability } from "@/lib/fusion/creative-studio/platform/ordinary-module-authoring";
import { resolveStudioControlAvailability, studioControlProps } from "@/lib/fusion/creative-studio/platform/control-availability";
import type { BrandPreviewContext } from "@/lib/fusion/creative-studio/reconstitution/standard-button-catalog";
import { applyStudioTextRole, evaluateStudioTextAccessibility, STUDIO_TEXT_AUTHORING_CONTRACT, STUDIO_TEXT_ROLES, studioTextRole, textRoleCanonicalProps } from "@/lib/fusion/creative-studio/platform/text-authoring";
import { FONT_CATALOG, fontCssStack, searchFonts } from "@/lib/fusion/creative-studio/fonts/catalog";
import { ensureFontLoaded } from "@/lib/fusion/creative-studio/fonts/load";
import { readContainerEdgeMode, setContainerEdgeMode, STUDIO_EDGE_MODES } from "@/lib/fusion/creative-studio/platform/edge-layout";
import { isCardSurfaceLayered, isLayeredContainer, layeredResizePolicy, reorderLayeredNodeZ, setContainerCompositionMode, type LayeredZCommand } from "@/lib/fusion/creative-studio/platform/layered-region";
import { readContainerDensity, setContainerDensity, type StudioCompositionDensityMode } from "@/lib/fusion/creative-studio/platform/composition-density";
import { applyStudioVideoPlayback, applyStudioVideoSource, readStudioVideoState, videoFeatureDefaults } from "@/lib/fusion/creative-studio/platform/media-module";
import { applySurfaceMaterial, getMaterialRecipe, materialPreviewCss } from "@/lib/fusion/creative-studio/material-engine";
import {
  computeGroupUnionBounds,
  compositionGroupRecord,
  groupMembers,
  moveCompositionGroupInBlock,
  readCompositionGroupSettings,
  reorderCompositionGroupZ,
  resolveActiveGroupId,
  resizeCompositionGroupInBlock,
  setCompositionGroupScaleMode,
  setCompositionGroupSettingsInBlock,
  ungroupCompositionBlock,
  type CompositionGroupDensityMode,
  type CompositionGroupLayoutMode,
  type CompositionGroupScaleMode,
} from "@/lib/fusion/creative-studio/group-authority";
import { StudioColorControl } from "./studio-color-control";
import { StudioInternalPagePicker } from "./studio-internal-page-picker";
import { StudioMapLocationInspector } from "./studio-map-location-inspector";

const ContainerBrandContext = createContext<BrandPreviewContext | null>(null);

export function StudioCompositionInspector({ model, node, brand, onClose }: {
  model: CardEditorLiveModel;
  node: CreativeCompositionNode;
  brand: BrandPreviewContext;
  onClose: () => void;
}) {
  const block = model.config.rootComposition;
  if (!block || !hasCompositionParentAuthority(block) || !node.compositionKind) return null;
  const parent = node.parentId ? block.nodes.find((candidate) => candidate.id === node.parentId) : null;
  const containers = block.nodes.filter((candidate) => candidate.compositionKind === "container");
  const selectedIds = model.selectedCompositionNodeIds ?? [node.id];
  const selectedModules = selectedIds.filter((id) => block.nodes.find((candidate) => candidate.id === id)?.compositionKind === "module");
  const activeGroupId = resolveActiveGroupId(block.nodes, selectedIds);
  const patchProps = (patch: Record<string, unknown>, label: string) => model.patchCompositionNode(node.id, { props: { ...node.props, ...patch } }, label);
  const label = activeGroupId ? "Group" : node.name || (node.compositionKind === "container" ? "Container" : String(node.props.elementKind || node.primitive));
  const ancestors: CreativeCompositionNode[] = [];
  let ancestor = parent;
  while (ancestor) {
    ancestors.unshift(ancestor);
    ancestor = ancestor.parentId ? block.nodes.find((candidate) => candidate.id === ancestor!.parentId) ?? null : null;
  }
  const breadcrumb = ["Card Surface", ...ancestors.map((candidate) => candidate.name || "Container"), label].join(" › ");
  return <aside className="absolute inset-x-0 bottom-0 z-[2100] flex max-h-[62dvh] flex-col rounded-t-3xl border-t border-white/8 bg-[#0b111b]/98 text-white shadow-[0_-18px_50px_rgba(0,0,0,.36)] backdrop-blur-xl md:inset-y-0 md:left-auto md:right-0 md:max-h-none md:w-[min(360px,calc(100vw-12px))] md:rounded-none md:border-l md:border-t-0 md:shadow-[-18px_0_50px_rgba(0,0,0,.36)]" data-testid="studio-composition-inspector">
    <header className="flex min-h-14 items-center gap-2 border-b border-white/8 px-4"><div className="min-w-0 flex-1"><p className="truncate text-xs text-white/45" title={breadcrumb} data-testid="studio-selection-breadcrumb">{breadcrumb}</p><h2 className="mt-0.5 text-sm font-semibold">{activeGroupId ? "Composition Group" : node.compositionKind === "container" ? "Container" : "Module"}</h2></div>{parent ? <button type="button" onClick={() => model.setSelectedCompositionNodeIds?.([parent.id])} className="min-h-9 rounded-full border border-white/10 px-3 text-[9px] text-white/62 hover:bg-white/8" data-testid="studio-select-parent">Parent</button> : null}<button type="button" onClick={onClose} className="grid h-9 w-9 place-items-center rounded-full hover:bg-white/8" aria-label="Close Inspector"><X className="h-4 w-4" /></button></header>
    <div className="min-h-0 flex-1 overflow-y-auto p-4">
      {activeGroupId ? <GroupControls groupId={activeGroupId} model={model} block={block} /> : node.compositionKind === "container" ? <>{isLayeredContainer(parent) || (!parent && isCardSurfaceLayered(block)) ? <LayeredPositionControls node={node} model={model} block={block} /> : null}<ContainerControls node={node} patchProps={patchProps} model={model} brand={brand} /></> : <ModuleControls node={node} parent={parent} containers={containers} model={model} block={block} brand={brand} />}
      {!activeGroupId && node.compositionKind === "module" && selectedModules.length > 0 ? <button type="button" onClick={() => model.onWrapCompositionModules?.(selectedModules)} className="mt-5 flex min-h-11 w-full items-center justify-center gap-2 rounded-xl bg-[#b8ff2c] px-3 text-xs font-semibold text-[#07100a]" data-testid="studio-wrap-modules"><Layers3 className="h-4 w-4" />Wrap {selectedModules.length > 1 ? `${selectedModules.length} Modules` : "in Container"}</button> : null}
      {!activeGroupId && node.compositionKind === "container" ? <button type="button" onClick={() => model.onUnwrapCompositionContainer?.(node.id)} className="mt-5 flex min-h-11 w-full items-center justify-center gap-2 rounded-xl border border-white/12 text-xs font-semibold" data-testid="studio-unwrap-container"><Ungroup className="h-4 w-4" />Remove Container, keep Modules</button> : null}
      {activeGroupId ? <button type="button" onClick={() => { const memberIds = groupMembers(block.nodes, activeGroupId).map((member) => member.id); model.patchConfig({ rootComposition: ungroupCompositionBlock(block, activeGroupId) }, "Ungrouped composition Group"); model.setSelectedCompositionNodeIds?.(memberIds); }} className="mt-5 flex min-h-11 w-full items-center justify-center gap-2 rounded-xl border border-white/12 text-xs font-semibold" data-testid="studio-composition-group-ungroup"><Ungroup className="h-4 w-4" />Ungroup, keep Modules</button> : null}
    </div>
  </aside>;
}

function GroupControls({ groupId, model, block }: { groupId: string; model: CardEditorLiveModel; block: NonNullable<CardEditorLiveModel["config"]["rootComposition"]> }) {
  const settings = readCompositionGroupSettings(block.nodes, groupId);
  const bounds = computeGroupUnionBounds(block.nodes, groupId, true);
  const record = compositionGroupRecord(block, groupId);
  const members = groupMembers(block.nodes, groupId);
  const parentId = members[0]?.parentId ?? null;
  const parent = parentId ? block.nodes.find((candidate) => candidate.id === parentId) : null;
  const region = { widthPx: 390, heightPx: parent ? Number(parent.props.layeredHeightPx ?? 360) : Number(block.compositionMode?.layeredHeightPx ?? 620) };
  const replace = (next: typeof block, label: string) => model.patchConfig({ rootComposition: next }, label);
  const settingsPatch = (patch: Parameters<typeof setCompositionGroupSettingsInBlock>[2], label: string) => replace(setCompositionGroupSettingsInBlock(block, groupId, patch, region), label);
  const geometry = (key: "left" | "top" | "width" | "height", value: number) => {
    if (!bounds) return;
    const normalized = Math.max(0, Math.min(100, value)) / 100;
    if (key === "left") replace(moveCompositionGroupInBlock(block, groupId, normalized - bounds.left, 0), "Changed Group X");
    else if (key === "top") replace(moveCompositionGroupInBlock(block, groupId, 0, normalized - bounds.top), "Changed Group Y");
    else replace(resizeCompositionGroupInBlock(block, groupId, { left: bounds.left, top: bounds.top, width: key === "width" ? Math.max(.08, normalized) : bounds.width, height: key === "height" ? Math.max(.06, normalized) : bounds.height }, { minChildWidth: 28 / region.widthPx, minChildHeight: 44 / region.heightPx }), `Changed Group ${key}`);
  };
  const scale = (scaleMode: CompositionGroupScaleMode) => replace(setCompositionGroupScaleMode(block, groupId, scaleMode, { minChildWidth: 28 / region.widthPx, minChildHeight: 44 / region.heightPx }), `Changed Group scale to ${scaleMode}`);
  const z = (command: "backward" | "forward" | "back" | "front", label: string) => replace(reorderCompositionGroupZ(block, groupId, command), label);
  return <div data-testid="studio-composition-group-controls">
    <ControlGroup label="Group position"><p className="text-[9px] leading-4 text-[#a9e7ff]/70">{members.length} canonical sibling Modules · persisted Group transform · one move or resize creates one history step.</p>{bounds ? <div className="grid grid-cols-2 gap-2">{([['left','X'],['top','Y'],['width','Width'],['height','Height']] as const).map(([key,label]) => <label key={key} className="text-[9px] text-white/48">{label}<input type="number" min={0} max={100} value={Math.round(bounds[key] * 100)} onChange={(event) => geometry(key, Number(event.target.value))} className="mt-1 h-9 w-full rounded-lg bg-white/5 px-2" data-testid={`studio-group-${key}`} /></label>)}</div> : null}<p className="mt-3 text-[9px] text-white/42">Anchor</p><Segmented values={["top-left","top","top-right","left","center","right","bottom-left","bottom","bottom-right"]} value={record?.anchor ?? "top-left"} onChange={(value) => replace({ ...block, groups: (block.groups ?? []).map((group) => group.id === groupId ? { ...group, anchor: value as NonNullable<typeof group.anchor> } : group) }, `Changed Group anchor to ${value}`)} label="Anchor" /></ControlGroup>
    <ControlGroup label="Scale / fit"><Segmented values={["fit","fill","proportional","compact","medium","full"]} value={record?.scaleMode ?? "proportional"} onChange={(value) => scale(value as CompositionGroupScaleMode)} label="Scale mode" /><p className="text-[9px] leading-4 text-white/38">Compact, Medium, and Full apply governed responsive widths. Curated artwork keeps its certified aspect ratio and every action retains a 44px minimum target.</p></ControlGroup>
    <ControlGroup label="Internal layout"><Segmented values={["layered","flow_vertical","flow_horizontal","grid"]} value={settings.layout} onChange={(value) => settingsPatch({ layout: value as CompositionGroupLayoutMode }, `Changed Group layout to ${value}`)} label="Layout" /><Segmented values={["dense","standard","airy","custom"]} value={settings.density} onChange={(value) => settingsPatch({ density: value as CompositionGroupDensityMode }, `Changed Group density to ${value}`)} label="Density" />{settings.density === "custom" ? <><StudioPrecisionControl label="Row gap" value={settings.rowGapPx} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 10 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => settingsPatch({ rowGapPx: value }, "Previewed Group row gap")} onCommit={() => model.commitLiveAdjustment?.("Changed Group row gap")} onCancel={model.cancelLiveAdjustment} /><StudioPrecisionControl label="Column gap" value={settings.columnGapPx} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 12 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => settingsPatch({ columnGapPx: value }, "Previewed Group column gap")} onCommit={() => model.commitLiveAdjustment?.("Changed Group column gap")} onCancel={model.cancelLiveAdjustment} /><StudioPrecisionControl label="Internal group gap" value={settings.internalGapPx} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 6 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => settingsPatch({ internalGapPx: value }, "Previewed Group internal gap")} onCommit={() => model.commitLiveAdjustment?.("Changed Group internal gap")} onCancel={model.cancelLiveAdjustment} /></> : <p className="text-[9px] text-white/35">{settings.rowGapPx}px rows · {settings.columnGapPx}px columns · {settings.internalGapPx}px inset</p>}</ControlGroup>
    <ControlGroup label="Local layer"><div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => z("back", "Sent composition Group to back")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Send to back</button><button type="button" onClick={() => z("backward", "Sent composition Group backward")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Send backward</button><button type="button" onClick={() => z("forward", "Brought composition Group forward")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Bring forward</button><button type="button" onClick={() => z("front", "Brought composition Group to front")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Bring to front</button></div></ControlGroup>
    <ControlGroup label="Group behavior"><div className="grid grid-cols-3 gap-2"><button type="button" onClick={() => replace({ ...block, nodes: block.nodes.map((candidate) => candidate.groupId === groupId ? { ...candidate, locked: true } : candidate), groups: (block.groups ?? []).map((group) => group.id === groupId ? { ...group, locked: true } : group) }, "Locked composition Group")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Lock Group</button><button type="button" onClick={() => replace({ ...block, nodes: block.nodes.map((candidate) => candidate.groupId === groupId ? { ...candidate, locked: false } : candidate), groups: (block.groups ?? []).map((group) => group.id === groupId ? { ...group, locked: false } : group) }, "Unlocked composition Group")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Unlock Group</button><button type="button" onClick={() => replace(ungroupCompositionBlock(block, groupId), "Ungrouped composition Group")} className="min-h-10 rounded-xl border border-white/10 text-[10px]" data-testid="studio-group-ungroup">Ungroup</button></div></ControlGroup>
  </div>;
}

function ContainerControls({ node, patchProps, model, brand }: { node: CreativeCompositionNode; patchProps: (patch: Record<string, unknown>, label: string) => void; model: CardEditorLiveModel; brand: BrandPreviewContext }) {
  const surface = readStudioSurfaceState(node.props);
  const transaction = (patch: Record<string, unknown>) => model.previewCompositionNode?.(node.id, { props: { ...node.props, ...patch } });
  const precision = (label: string) => ({ onBegin: model.beginLiveAdjustment, onCommit: () => model.commitLiveAdjustment?.(label), onCancel: model.cancelLiveAdjustment });
  const surfacePatch = (patch: Parameters<typeof applyStudioSurfaceParameters>[1]) => transaction(applyStudioSurfaceParameters(node.props, patch));
  const showEdge = surface.treatment !== "transparent" || surface.borderWidthPx > 0;
  const imageTuneAvailability = resolveStudioControlAvailability({ availability: surface.mediaUrl ? "enabled" : "disabled", dependency: "image-asset", disabledReason: surface.mediaUrl ? undefined : "Choose an image before tuning its presentation.", governance: "direct" });
  const layout = isLayeredContainer(node) ? "layered" : ["flow_horizontal", "grid"].includes(String(node.props.layout)) ? String(node.props.layout) : "flow";
  const density = readContainerDensity(node);
  const edgeMode = readContainerEdgeMode(node.props);
  const leather = getMaterialRecipe("worn_saddle_leather")!;
  const layoutGuidance = layout === "layered" ? "Place and overlap items freely." : layout === "flow_horizontal" ? "Arrange items side by side." : layout === "grid" ? "Arrange items in rows and columns." : "Arrange items in order.";
  return <ContainerBrandContext.Provider value={brand}><p className="mb-3 rounded-xl border border-[#8bdcff]/12 bg-[#8bdcff]/[.035] px-3 py-2 text-[10px] text-[#c9efff]/75" data-testid="studio-layout-guidance"><strong className="uppercase">{layout === "flow_horizontal" ? "Horizontal" : layout}</strong> · {layoutGuidance}</p><div data-control-group="surface" data-catalog-adapter="surface-treatments" data-semantic-state="structure">
    <section data-testid="studio-container-layout-mode"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">Composition</p><p className="mt-1 text-[9px] leading-4 text-white/38">Structured flow may run vertically, horizontally, or as a paired grid. Layered keeps free placement bounded inside this region.</p><div className="mt-3 grid grid-cols-2 gap-1">{(["flow","flow_horizontal","grid","layered"] as const).map((mode) => <button key={mode} type="button" aria-pressed={layout === mode} onClick={() => { const root = model.config.rootComposition; if (!root) return; const seeded = setContainerCompositionMode(root, node.id, mode === "layered" ? "layered" : "flow"); const next = mode === "flow" || mode === "layered" ? seeded : { ...seeded, nodes: seeded.nodes.map((candidate) => candidate.id === node.id ? { ...candidate, props: { ...candidate.props, layout: mode } } : candidate) }; model.patchConfig({ rootComposition: next }, `Changed Container composition to ${mode}`); }} className="min-h-10 rounded-xl bg-white/5 px-1 text-[9px] capitalize aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]">{mode.replace("flow_", "")}</button>)}</div><p className="mt-4 text-[9px] font-semibold uppercase tracking-[.12em] text-white/42">Density</p><div className="mt-2 grid grid-cols-4 gap-1">{(["dense","standard","airy","custom"] as StudioCompositionDensityMode[]).map((mode) => <button key={mode} type="button" aria-pressed={density.mode === mode} onClick={() => patchProps(setContainerDensity(node.props, mode), `Changed Container density to ${mode}`)} className="min-h-9 rounded-lg bg-white/5 px-1 text-[8px] capitalize aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]">{mode}</button>)}</div>{density.mode === "custom" ? <><StudioPrecisionControl label={layout === "layered" ? "Snap rhythm / row gap" : "Row gap"} value={density.rowGapPx} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 16 }} onPreview={(value) => transaction(setContainerDensity(node.props, "custom", value, { rowGapPx: value }))} {...precision("Changed Container row gap")} /><StudioPrecisionControl label="Column gap" value={density.columnGapPx} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 16 }} onPreview={(value) => transaction(setContainerDensity(node.props, "custom", density.gapPx, { columnGapPx: value }))} {...precision("Changed Container column gap")} /><StudioPrecisionControl label="Internal group gap" value={density.internalGroupGapPx} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 8 }} onPreview={(value) => transaction(setContainerDensity(node.props, "custom", density.gapPx, { internalGroupGapPx: value }))} {...precision("Changed Container internal group gap")} /></> : <p className="mt-2 text-[9px] text-white/35">{layout === "layered" ? `${Math.round(density.snapGrid * 100)}% placement rhythm` : `${density.rowGapPx}px rows · ${density.columnGapPx}px columns`}</p>}{layout === "layered" ? <StudioPrecisionControl label="Layered region height" value={Number(node.props.layeredHeightPx ?? 360)} descriptor={{ unit: "px", min: 180, max: 900, step: 10, fineStep: 1, defaultValue: 360 }} onPreview={(value) => transaction({ layeredHeightPx: value })} {...precision("Changed layered region height")} /> : null}</section>
    <section className="mt-6" data-testid="studio-container-responsive-size"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">Responsive size</p><p className="mt-1 text-[9px] leading-4 text-white/38">Width is parent-relative and survives phone rendering. Use 35/65 or 40/60 for side-by-side regions.</p><Segmented values={["auto","25","33","40","50","66","75","100"]} value={node.props.widthPercent == null && node.props.flowWidthPercent == null ? "auto" : String(Math.round(Number(node.props.widthPercent ?? node.props.flowWidthPercent ?? 100)))} onChange={(value) => patchProps({ widthPercent: value === "auto" ? undefined : Number(value) }, value === "auto" ? "Changed Container width to Auto" : `Changed Container width to ${value}%`)} label="Width preset" /><StudioPrecisionControl label="Custom width" value={Number(node.props.widthPercent ?? node.props.flowWidthPercent ?? 100)} descriptor={{ unit: "%", min: 20, max: 100, step: 1, defaultValue: 100 }} onPreview={(value) => transaction({ widthPercent: value })} {...precision("Changed Container width")} /><div className="grid grid-cols-3 gap-2"><label className="text-[9px] text-white/48">Min width<input type="number" min={0} max={390} value={Number(node.props.minWidthPx ?? 0)} onChange={(event) => patchProps({ minWidthPx: Number(event.target.value) }, "Changed Container minimum width")} className="mt-1 h-9 w-full rounded-lg bg-white/5 px-2" /></label><label className="text-[9px] text-white/48">Max width<input type="number" min={80} max={1200} value={Number(node.props.maxWidthPx ?? 1200)} onChange={(event) => patchProps({ maxWidthPx: Number(event.target.value) }, "Changed Container maximum width")} className="mt-1 h-9 w-full rounded-lg bg-white/5 px-2" /></label><label className="text-[9px] text-white/48">Min height<input type="number" min={0} max={900} value={Number(node.props.minHeightPx ?? 0)} onChange={(event) => patchProps({ minHeightPx: Number(event.target.value) }, "Changed Container minimum height")} className="mt-1 h-9 w-full rounded-lg bg-white/5 px-2" /></label></div><Segmented values={["fit_content","fixed","fill_parent"]} value={String(node.props.contentFit || "fit_content")} onChange={(value) => patchProps({ contentFit: value }, `Changed Container fit to ${value}`)} label="Content fit" />{node.props.contentFit === "fixed" ? <StudioPrecisionControl label="Height" value={Number(node.props.heightPx ?? 240)} descriptor={{ unit: "px", min: 88, max: 900, step: 4, defaultValue: 240 }} onPreview={(value) => transaction({ heightPx: value })} {...precision("Changed Container height")} /> : null}<Segmented values={["auto","1:1","4:3","16:9"]} value={String(node.props.aspectRatio || "auto")} onChange={(value) => patchProps({ aspectRatio: value }, `Changed Container aspect ratio to ${value}`)} label="Aspect ratio" /><label className="mt-3 flex min-h-10 items-center justify-between rounded-xl bg-white/4 px-3 text-[9px]"><span>Clip content intentionally</span><input type="checkbox" checked={node.props.clipContent === true} onChange={(event) => patchProps({ clipContent: event.target.checked }, `${event.target.checked ? "Enabled" : "Disabled"} Container clipping`)} /></label></section>
    <section className="mt-6" data-testid="studio-container-edge-mode"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">Surface edge</p><div className="mt-2 grid grid-cols-3 gap-1">{STUDIO_EDGE_MODES.map((option) => <button key={option.id} type="button" aria-pressed={edgeMode === option.id} onClick={() => patchProps(setContainerEdgeMode(node.props, option.id), `Changed Container edge to ${option.label}`)} className="min-h-11 rounded-lg bg-white/5 px-1 text-[9px] aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]">{option.label}</button>)}</div></section>
    <section className="mt-6"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">Surface</p><div className="mt-3 grid grid-cols-2 gap-2">{STUDIO_SURFACE_TREATMENTS.map((option) => <button key={option.id} type="button" aria-pressed={surface.treatment === option.id} onClick={() => patchProps(applyStudioSurfaceTreatment(node.props, option.id), `Changed Container surface to ${option.label}`)} className={cn("min-h-20 overflow-hidden rounded-xl border border-white/10 bg-white/4 text-left text-[11px]", "aria-pressed:border-[#b8ff2c] aria-pressed:bg-[#b8ff2c]/10 aria-pressed:text-[#d8ff82]")}><span className="block h-8 w-full" style={{ background: option.preview }} /><span className="block px-2 pt-1.5 font-medium">{option.label}</span><span className="block px-2 pb-2 text-[8px] leading-3 text-white/35">{option.description}</span></button>)}</div><button type="button" aria-pressed={node.props.materialPreset === leather.id} onClick={() => patchProps(applySurfaceMaterial(node.props, leather.id), "Applied Worn Saddle Leather Container Surface")} className="mt-3 w-full overflow-hidden rounded-xl border border-white/10 bg-white/4 text-left aria-pressed:border-[#b8ff2c] aria-pressed:bg-[#b8ff2c]/10"><span className="block h-12" style={{ background: materialPreviewCss(leather) }} /><span className="block px-3 py-2 text-[10px] font-semibold">Worn Saddle Leather</span></button></section>
    {surface.treatment === "image" ? <section className="mt-6 rounded-2xl border border-[#8bdcff]/12 bg-[#101824]/70 p-3" data-testid="studio-container-image-controls"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">Image</p><div className="mt-2"><MediaPicker label="Container image" chooseLabel="Choose image" replaceLabel="Replace image" removeLabel="Remove" value={surface.mediaUrl || ""} valueAssetId={surface.mediaAssetId} mediaUploadReady={model.mediaUploadReady} stockReady={model.stockReady} onAssetChange={(asset) => patchProps(applyStudioSurfaceTreatment(node.props, "image", asset ? { mediaUrl: asset.url, mediaAssetId: asset.mediaAssetId || asset.id } : { mediaUrl: undefined, mediaAssetId: undefined }), asset ? "Selected Container image" : "Removed Container image")} /></div><fieldset className="disabled:opacity-35" {...studioControlProps(imageTuneAvailability)}><p className="mt-4 text-[9px] font-semibold uppercase tracking-[.14em] text-white/42">Presentation</p>{imageTuneAvailability.disabledReason ? <p className="mt-1 text-[9px] text-amber-100/70">{imageTuneAvailability.disabledReason}</p> : null}<div className="mt-2 grid grid-cols-3 gap-1">{(["cover","contain","fill"] as const).map((fit) => <button key={fit} type="button" aria-pressed={surface.fit === fit} onClick={() => patchProps(applyStudioSurfaceParameters(node.props, { fit }), `Changed Container image fit to ${fit}`)} className="min-h-9 rounded-lg bg-white/5 text-[9px] capitalize aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]">{fit}</button>)}</div><StudioPrecisionControl label="Zoom / scale" value={Math.round(surface.scale * 100)} descriptor={{ unit: "%", min: 50, max: 250, step: 1, defaultValue: 100 }} onPreview={(value) => surfacePatch({ scale: value / 100 })} {...precision("Changed Container image scale")} /><StudioPrecisionControl label="Focal point X" value={Math.round(surface.focalX * 100)} descriptor={{ unit: "%", min: 0, max: 100, step: 1, defaultValue: 50 }} onPreview={(value) => surfacePatch({ focalX: value / 100 })} {...precision("Changed Container image focal point")} /><StudioPrecisionControl label="Focal point Y" value={Math.round(surface.focalY * 100)} descriptor={{ unit: "%", min: 0, max: 100, step: 1, defaultValue: 50 }} onPreview={(value) => surfacePatch({ focalY: value / 100 })} {...precision("Changed Container image focal point")} /><p className="mt-5 text-[9px] font-semibold uppercase tracking-[.14em] text-white/42">Image treatment</p><LiveColorWell label="Tint / veil" value={surface.tint} node={node} model={model} apply={(value) => applyStudioSurfaceParameters(node.props, { tint: value })} historyLabel="Changed Container image tint" /><StudioPrecisionControl label="Brightness" value={Math.round(surface.brightness * 100)} descriptor={{ unit: "%", min: 25, max: 200, step: 1, defaultValue: 100 }} onPreview={(value) => surfacePatch({ brightness: value / 100 })} {...precision("Changed Container image brightness")} /><StudioPrecisionControl label="Contrast" value={Math.round(surface.contrast * 100)} descriptor={{ unit: "%", min: 25, max: 200, step: 1, defaultValue: 100 }} onPreview={(value) => surfacePatch({ contrast: value / 100 })} {...precision("Changed Container image contrast")} /><StudioPrecisionControl label="Saturation" value={Math.round(surface.saturation * 100)} descriptor={{ unit: "%", min: 0, max: 200, step: 1, defaultValue: 100 }} onPreview={(value) => surfacePatch({ saturation: value / 100 })} {...precision("Changed Container image saturation")} /><StudioPrecisionControl label="Overlay / veil" value={Math.round(surface.overlayOpacity * 100)} descriptor={{ unit: "%", min: 0, max: 90, step: 1, defaultValue: 28 }} onPreview={(value) => surfacePatch({ overlayOpacity: value / 100 })} {...precision("Changed Container image veil")} /><StudioPrecisionControl label="Image opacity" value={Math.round(surface.imageOpacity * 100)} descriptor={{ unit: "%", min: 10, max: 100, step: 1, defaultValue: 100 }} onPreview={(value) => surfacePatch({ imageOpacity: value / 100 })} {...precision("Changed Container image opacity")} /></fieldset></section> : null}
    {surface.treatment === "solid" || surface.treatment === "smoked_glass" ? <section className="mt-6"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">{surface.treatment === "smoked_glass" ? "Glass" : "Color"}</p><LiveColorWell label={surface.treatment === "smoked_glass" ? "Fill / tint" : "Fill"} value={surface.fill?.startsWith("#") ? surface.fill : "#162019"} node={node} model={model} apply={(value) => applyStudioSurfaceParameters(node.props, { fill: value })} historyLabel="Changed Container fill" /><StudioPrecisionControl label={surface.treatment === "smoked_glass" ? "Translucency" : "Opacity"} value={Math.round(surface.opacity * 100)} descriptor={{ unit: "%", min: 10, max: 100, step: 1, defaultValue: surface.treatment === "smoked_glass" ? 72 : 100 }} onPreview={(value) => surfacePatch({ opacity: value / 100 })} {...precision("Changed Container opacity")} />{surface.treatment === "smoked_glass" ? <StudioPrecisionControl label="Glass blur" value={surface.blurPx} descriptor={{ unit: "px", min: 0, max: 32, step: 1, fineStep: .5, defaultValue: 14 }} onPreview={(value) => surfacePatch({ blurPx: value })} {...precision("Changed Container glass blur")} /> : null}</section> : null}
    <section className="mt-6"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">Edge</p><LiveColorWell label="Border / rim" value={surface.borderColor.startsWith("#") ? surface.borderColor : "#ffffff"} node={node} model={model} apply={(value) => applyStudioSurfaceParameters(node.props, { borderColor: value })} historyLabel="Changed Container border color" /><StudioPrecisionControl label="Border width" value={surface.borderWidthPx} descriptor={{ unit: "px", min: 0, max: 8, step: 1, fineStep: .5, defaultValue: surface.treatment === "transparent" ? 0 : 1 }} onPreview={(value) => surfacePatch({ borderWidthPx: value })} {...precision("Changed Container border width")} />{showEdge ? <StudioPrecisionControl label="Corner radius" value={surface.radiusPx} descriptor={{ unit: "px", min: 0, max: 48, step: 1, fineStep: .5, defaultValue: 16 }} onPreview={(value) => surfacePatch({ radiusPx: value })} {...precision("Changed Container corner radius")} /> : null}{surface.treatment !== "transparent" ? <StudioPrecisionControl label="Shadow / depth" value={surface.shadowPx} descriptor={{ unit: "px", min: 0, max: 48, step: 1, defaultValue: 18 }} onPreview={(value) => surfacePatch({ shadowPx: value })} {...precision("Changed Container depth")} /> : null}</section>
    <section className="mt-6"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">Flow spacing</p><StudioPrecisionControl label="Space before" value={Number(node.props.spacingAbovePx ?? 0)} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 0 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => transaction({ spacingAbovePx: value })} onCommit={() => model.commitLiveAdjustment?.("Changed Container space before")} onCancel={model.cancelLiveAdjustment} /><StudioPrecisionControl label="Space after" value={Number(node.props.spacingBelowPx ?? 0)} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 0 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => transaction({ spacingBelowPx: value })} onCommit={() => model.commitLiveAdjustment?.("Changed Container space after")} onCancel={model.cancelLiveAdjustment} /><StudioPrecisionControl label="Padding" value={Number(node.props.padding ?? 16)} descriptor={{ unit: "px", min: 0, max: 48, step: 1, fineStep: .5, defaultValue: 16 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => transaction({ padding: value })} onCommit={() => model.commitLiveAdjustment?.("Changed Container padding")} onCancel={model.cancelLiveAdjustment} /><StudioPrecisionControl label="Internal gap" value={Number(node.props.gap ?? 12)} descriptor={{ unit: "px", min: 0, max: 40, step: 1, fineStep: .5, defaultValue: 12 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => transaction({ gap: value })} onCommit={() => model.commitLiveAdjustment?.("Changed Container gap")} onCancel={model.cancelLiveAdjustment} /></section>
    <section className="mt-6"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-white/42">Alignment</p><div className="mt-2 grid grid-cols-4 gap-1">{['start','center','end','stretch'].map((value) => <button key={value} type="button" aria-pressed={String(node.props.alignment || 'stretch') === value} onClick={() => patchProps({ alignment: value }, `Changed Container alignment to ${value}`)} className="min-h-9 rounded-lg bg-white/5 text-[9px] capitalize aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]">{value}</button>)}</div></section>
  </div></ContainerBrandContext.Provider>;
}

function LiveColorWell({ label, value, node, model, apply, historyLabel }: { label: string; value: string; node: CreativeCompositionNode; model: CardEditorLiveModel; apply: (value: string) => Record<string, unknown>; historyLabel: string }) {
  const brand = useContext(ContainerBrandContext);
  const brandColors = brand ? [brand.primaryColor, brand.secondaryColor, brand.accentColor, brand.backgroundColor].filter((candidate): candidate is string => Boolean(candidate && /^#[0-9a-f]{6}$/i.test(candidate))) : [];
  const resetValue = brand?.backgroundColor && /^#[0-9a-f]{6}$/i.test(brand.backgroundColor) ? brand.backgroundColor : "#000000";
  return <div className="mt-2"><StudioColorControl label={label} value={hex(value, "#000000")} source={node.props.colorSource === "brand" ? "brand" : "custom"} brandColors={brandColors} resetValue={resetValue} resetLabel="Reset to Brand" onChange={(next, source) => model.patchCompositionNode(node.id, { props: { ...node.props, ...apply(next), colorSource: source } }, historyLabel)} /></div>;
}

function ModuleControls({ node, parent, containers, model, block, brand }: { node: CreativeCompositionNode; parent?: CreativeCompositionNode | null; containers: CreativeCompositionNode[]; model: CardEditorLiveModel; block: NonNullable<CardEditorLiveModel["config"]["rootComposition"]>; brand: BrandPreviewContext }) {
  const siblings = compositionChildren(block, node.parentId ?? null);
  const siblingIndex = siblings.findIndex((candidate) => candidate.id === node.id);
  const preview = (patch: Record<string, unknown>) => model.previewCompositionNode?.(node.id, { props: { ...node.props, ...patch } });
  const patch = (values: Record<string, unknown>, label: string) => model.patchCompositionNode(node.id, { props: { ...node.props, ...values } }, label);
  const precision = (label: string) => ({ onBegin: model.beginLiveAdjustment, onCommit: () => model.commitLiveAdjustment?.(label), onCancel: model.cancelLiveAdjustment });
  const capability = resolveOrdinaryModuleCapability(node);
  const kind = ordinaryModuleKind(node);
  const isMap = node.props.elementKind === "map" || node.props.componentKind === "map";
  return <>
    {isLayeredContainer(parent) || (!parent && isCardSurfaceLayered(block)) ? <LayeredPositionControls node={node} model={model} block={block} /> : null}
    {isMap ? <StudioMapLocationInspector node={node} model={model} /> : null}
    {!isMap ? <>
    {node.primitive === "image" ? <ControlGroup label="Layer tint"><ColorInput label="Tint color" value={hex(node.props.layerTintColor, "#000000")} onChange={(value) => patch({ layerTintColor: value }, "Changed Image layer tint")} /><StudioPrecisionControl label="Tint opacity" value={Math.round(Number(node.props.layerTintOpacity ?? 0) * 100)} descriptor={{ unit: "%", min: 0, max: 100, step: 1, defaultValue: 0 }} onPreview={(value) => preview({ layerTintOpacity: value / 100 })} {...precision("Changed Image layer tint opacity")} /></ControlGroup> : null}
    <div data-ordinary-module-contract={capability?.contractId} data-ordinary-module-kind={kind ?? undefined} data-in-layered-container={isLayeredContainer(parent) ? "true" : "false"}>
    {kind === "text" ? <TextControls node={node} model={model} block={block} brand={brand} /> : null}
    {node.primitive === "image" ? <div className="rounded-xl bg-white/4 p-3"><MediaPicker label="Module image" value={String(node.props.src || "")} valueAssetId={typeof node.props.mediaAssetId === "string" ? node.props.mediaAssetId : undefined} mediaUploadReady={model.mediaUploadReady} stockReady={model.stockReady} onAssetChange={(asset) => model.patchCompositionNode(node.id, { props: asset ? { ...node.props, src: asset.url, mediaSrc: asset.url, mediaAssetId: asset.mediaAssetId || asset.id, alt: asset.label || node.props.alt || "Card image" } : { ...node.props, src: "", mediaSrc: "", mediaAssetId: undefined } }, asset ? "Selected Module image asset" : "Cleared Module image asset")} /></div> : null}
    {node.primitive === "video" ? <VideoControls node={node} model={model} /> : null}
    {kind === "divider" ? <>
      <ControlGroup label="Line"><ColorInput label="Color" value={hex(node.props.color, "#f8fafc")} onChange={(value) => patch({ color: value }, "Changed Divider color")} /><StudioPrecisionControl label="Thickness" value={Number(node.props.thickness ?? 2)} descriptor={{ unit: "px", min: 1, max: 16, step: 1, fineStep: .5, defaultValue: 2 }} onPreview={(value) => preview({ thickness: value })} {...precision("Changed Divider thickness")} /><StudioPrecisionControl label="Opacity" value={Math.round(Number(node.props.opacity ?? 1) * 100)} descriptor={{ unit: "%", min: 10, max: 100, step: 1, defaultValue: 100 }} onPreview={(value) => preview({ opacity: value / 100 })} {...precision("Changed Divider opacity")} /><Segmented values={["solid","dashed","dotted","double"]} value={String(node.props.style || "solid")} onChange={(value) => patch({ style: value }, `Changed Divider style to ${value}`)} label="Style" /><Segmented values={["clean","soft-glow","metallic"]} value={String(node.props.decorativeTreatment || "clean")} onChange={(value) => patch({ decorativeTreatment: value }, `Changed Divider treatment to ${value}`)} label="Treatment" /></ControlGroup>
      <ControlGroup label="Width and alignment"><StudioPrecisionControl label="Width" value={Number(node.props.flowWidthPercent ?? 100)} descriptor={{ unit: "%", min: 20, max: 100, step: 1, defaultValue: 100 }} onPreview={(value) => preview({ flowWidthPercent: value })} {...precision("Changed Divider width")} /><StudioPrecisionControl label="Inset" value={Number(node.props.flowInsetPx ?? 0)} descriptor={{ unit: "px", min: 0, max: 80, step: 1, fineStep: .5, defaultValue: 0 }} onPreview={(value) => preview({ flowInsetPx: value })} {...precision("Changed Divider inset")} /><Segmented values={["start","center","end","stretch"]} value={String(node.props.flowAlignment || "stretch")} onChange={(value) => patch({ flowAlignment: value }, `Aligned Divider ${value}`)} label="Alignment" /></ControlGroup>
    </> : null}
    {kind === "image" && capability?.controls.imageTreatment ? <ControlGroup label="Image treatment"><fieldset className="space-y-3 disabled:opacity-35" {...studioControlProps(capability.controls.imageTreatment)}><p className="text-[10px] text-white/42">{capability.controls.imageTreatment.disabledReason || "Tune the selected image without reopening discovery."}</p><Segmented values={["cover","contain","fill"]} value={String(node.props.fit || "cover")} onChange={(value) => patch({ fit: value }, `Changed Image fit to ${value}`)} label="Fit" /><StudioPrecisionControl label="Brightness" value={Math.round(Number(node.props.brightness ?? 1) * 100)} descriptor={{ unit: "%", min: 25, max: 200, step: 1, defaultValue: 100 }} onPreview={(value) => preview({ brightness: value / 100 })} {...precision("Changed Image brightness")} /><Segmented values={["meaningful","decorative"]} value={node.props.decorative === true ? "decorative" : "meaningful"} onChange={(value) => patch({ decorative: value === "decorative", alt: value === "decorative" ? "" : String(node.props.alt || "Card image"), clickThrough: value === "decorative" }, `Marked Image ${value}`)} label="Meaning" /><label className="flex min-h-10 items-center justify-between rounded-xl bg-white/4 px-3 text-[10px]"><span>Lock layer</span><input type="checkbox" checked={node.locked === true} onChange={(event) => model.patchCompositionNode(node.id, { locked: event.target.checked }, `${event.target.checked ? "Locked" : "Unlocked"} Image layer`)} /></label>{node.props.decorative !== true ? <label className="block text-[10px] text-white/58">Alternative text<input value={String(node.props.alt || "")} onChange={(event) => patch({ alt: event.target.value }, "Changed Image alternative text")} className="mt-1.5 h-10 w-full rounded-lg border border-white/12 bg-black/20 px-3 text-sm outline-none" /></label> : null}</fieldset></ControlGroup> : null}
    </div>
    </> : null}
    <section className={node.primitive === "text" ? "mt-6" : ""}><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#8bdcff]/70">Position · Flow placement</p><p className="mt-1 text-[11px] text-white/40">Parent: {parent?.name || "Card Surface"} · Position {siblingIndex + 1} of {siblings.length}</p><div className="mt-3 grid grid-cols-2 gap-2"><button type="button" disabled={siblingIndex <= 0} onClick={() => model.onReorderCompositionNode?.(node.id, siblingIndex - 1)} className="min-h-10 rounded-xl border border-white/10 bg-white/4 text-xs disabled:opacity-25">Move earlier</button><button type="button" disabled={siblingIndex < 0 || siblingIndex >= siblings.length - 1} onClick={() => model.onReorderCompositionNode?.(node.id, siblingIndex + 1)} className="min-h-10 rounded-xl border border-white/10 bg-white/4 text-xs disabled:opacity-25">Move later</button></div>{kind !== "divider" ? <><StudioPrecisionControl label="Width" value={Number(node.props.flowWidthPercent ?? 100)} descriptor={{ unit: "%", min: 20, max: 100, step: 1, defaultValue: 100 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => preview({ flowWidthPercent: value })} onCommit={() => model.commitLiveAdjustment?.("Changed Module width")} onCancel={model.cancelLiveAdjustment} /><StudioPrecisionControl label="Side inset" value={Number(node.props.flowInsetPx ?? 0)} descriptor={{ unit: "px", min: 0, max: 80, step: 1, fineStep: .5, defaultValue: 0 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => preview({ flowInsetPx: value })} onCommit={() => model.commitLiveAdjustment?.("Changed Module inset")} onCancel={model.cancelLiveAdjustment} /><div className="mt-3 grid grid-cols-4 gap-1" aria-label="Module alignment">{["start","center","end","stretch"].map((value) => <button key={value} type="button" aria-pressed={String(node.props.flowAlignment || "stretch") === value} onClick={() => model.patchCompositionNode(node.id, { props: { ...node.props, flowAlignment: value } }, `Changed Module alignment to ${value}`)} className="min-h-9 rounded-lg bg-white/5 text-[9px] capitalize aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]">{value}</button>)}</div></> : null}<StudioPrecisionControl label="Space before" value={Number(node.props.spacingAbovePx ?? 0)} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 0 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => preview({ spacingAbovePx: value })} onCommit={() => model.commitLiveAdjustment?.("Changed Module space before")} onCancel={model.cancelLiveAdjustment} /><StudioPrecisionControl label="Space after" value={Number(node.props.spacingBelowPx ?? 0)} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 0 }} onBegin={model.beginLiveAdjustment} onPreview={(value) => preview({ spacingBelowPx: value })} onCommit={() => model.commitLiveAdjustment?.("Changed Module space after")} onCancel={model.cancelLiveAdjustment} /><div className="mt-3 rounded-xl border border-white/8 bg-white/[.025] p-2"><p className="px-1 pb-2 text-[10px] text-white/58">Move to another parent</p><div className="space-y-1"><button type="button" aria-pressed={!node.parentId} onClick={() => model.onReparentCompositionModule?.(node.id, null)} className="w-full rounded-lg bg-white/5 px-3 py-2 text-left text-xs aria-pressed:bg-[#b8ff2c]/12 aria-pressed:text-[#d8ff82]">Card Surface</button>{containers.map((container) => <button key={container.id} type="button" aria-pressed={node.parentId === container.id} onClick={() => model.onReparentCompositionModule?.(node.id, container.id)} className="w-full rounded-lg bg-white/5 px-3 py-2 text-left text-xs aria-pressed:bg-[#b8ff2c]/12 aria-pressed:text-[#d8ff82]">{container.name || "Container"}</button>)}</div></div><p className="mt-3 text-[9px] leading-4 text-white/34">This changes composition membership and flow order. Front/back stacking appears only when overlapping Modules support true z-order.</p></section>
  </>;
}

function VideoControls({ node, model }: { node: CreativeCompositionNode; model: CardEditorLiveModel }) {
  const state = readStudioVideoState(node.props);
  const patch = (props: Record<string, unknown>, label: string) => model.patchCompositionNode(node.id, { props }, label);
  return <div data-testid="studio-video-controls">
    <ControlGroup label="Presentation">
      <Segmented values={["standard","feature"]} value={state.presentation} onChange={(value) => patch(value === "feature" ? { ...node.props, ...videoFeatureDefaults(), videoPresentation: "feature" } : { ...node.props, videoPresentation: "standard" }, `Changed Video presentation to ${value}`)} label="Video presentation" />
      <p className="text-[9px] leading-4 text-white/40">Feature keeps the canonical Video source and playback, then adds an intentional poster, editorial content, and shared frame treatment.</p>
      <Segmented values={["16:9","1:1","9:16"]} value={state.aspect} onChange={(value) => patch({ ...node.props, videoAspect: value, aspectLocked: true }, `Changed Video aspect to ${value}`)} label="Aspect" />
    </ControlGroup>
    <ControlGroup label="Video source">
      <label className="block text-[10px] text-white/58">YouTube, Vimeo, hosted, or direct media source<input value={state.sourceUrl} placeholder="https://… or /media/video.mp4" onChange={(event) => patch(applyStudioVideoSource(node.props, event.target.value), "Changed Video source")} className="mt-1.5 h-10 w-full rounded-lg border border-white/12 bg-black/20 px-3 text-sm outline-none focus:border-[#b8ff2c]" /></label>
      <p className="text-[9px] text-white/38">Detected provider: <strong className="text-white/68">{state.provider}</strong>. Provider adapters stay behind the same Video contract.</p>
    </ControlGroup>
    <ControlGroup label="Playback">
      <Segmented values={["play_on_tap","autoplay_muted"]} value={state.playbackMode} onChange={(value) => patch(applyStudioVideoPlayback(node.props, value as "play_on_tap" | "autoplay_muted"), `Changed Video playback to ${value}`)} label="Start behavior" />
      {state.playbackMode === "autoplay_muted" ? <p className="rounded-xl bg-amber-200/8 p-2 text-[9px] leading-4 text-amber-100/75">Legacy muted autoplay remains preserved. Phase 2.1 prioritizes poster → tap → inline playback; autoplay-in-view orchestration is deferred.</p> : <p className="rounded-xl bg-[#b8ff2c]/8 p-2 text-[9px] leading-4 text-[#d8ff82]/75">Recommended: the visitor intentionally taps Play and remains in the Experience.</p>}
      <div className="grid grid-cols-2 gap-2">{([['controls','Show controls'],['loop','Loop'],['playOnce','Play once'],['playsInline','Play inline']] as const).map(([key,label]) => <label key={key} className="flex min-h-10 items-center justify-between rounded-xl bg-white/4 px-3 text-[9px]"><span>{label}</span><input type="checkbox" checked={state[key]} onChange={(event) => patch({ ...node.props, [key]: event.target.checked, ...(key === "loop" && event.target.checked ? { playOnce: false } : {}), ...(key === "playOnce" && event.target.checked ? { loop: false } : {}) }, `Changed Video ${label}`)} /></label>)}</div>
      <div className="grid grid-cols-2 gap-2"><label className="text-[9px] text-white/48">Start (seconds)<input type="number" min={0} value={state.startSeconds} onChange={(event) => patch({ ...node.props, startSeconds: Number(event.target.value) }, "Changed Video start time")} className="mt-1 h-9 w-full rounded-lg bg-white/5 px-2" /></label><label className="text-[9px] text-white/48">End (optional)<input type="number" min={0} value={state.endSeconds ?? ""} onChange={(event) => patch({ ...node.props, endSeconds: event.target.value ? Number(event.target.value) : undefined }, "Changed Video end time")} className="mt-1 h-9 w-full rounded-lg bg-white/5 px-2" /></label></div>
    </ControlGroup>
    <ControlGroup label="Poster"><MediaPicker label="Video poster" value={state.posterUrl || ""} valueAssetId={state.posterMediaAssetId} mediaUploadReady={model.mediaUploadReady} stockReady={model.stockReady} onAssetChange={(asset) => patch({ ...node.props, posterUrl: asset?.url, posterMediaAssetId: asset ? asset.mediaAssetId || asset.id : undefined }, asset ? "Selected Video poster" : "Removed Video poster")} />{state.presentation === "feature" ? <><Segmented values={["cover","contain"]} value={state.posterFit} onChange={(value) => patch({ ...node.props, posterFit: value }, `Changed Video poster fit to ${value}`)} label="Poster fit" /><StudioPrecisionControl label="Poster focal X" value={Math.round(state.posterFocalX * 100)} descriptor={{ unit: "%", min: 0, max: 100, step: 1, defaultValue: 50 }} onPreview={(value) => model.previewCompositionNode?.(node.id, { props: { ...node.props, posterFocalX: value / 100 } })} onBegin={model.beginLiveAdjustment} onCommit={() => model.commitLiveAdjustment?.("Changed Video poster focal X")} onCancel={model.cancelLiveAdjustment} /><StudioPrecisionControl label="Poster focal Y" value={Math.round(state.posterFocalY * 100)} descriptor={{ unit: "%", min: 0, max: 100, step: 1, defaultValue: 50 }} onPreview={(value) => model.previewCompositionNode?.(node.id, { props: { ...node.props, posterFocalY: value / 100 } })} onBegin={model.beginLiveAdjustment} onCommit={() => model.commitLiveAdjustment?.("Changed Video poster focal Y")} onCancel={model.cancelLiveAdjustment} /></> : null}</ControlGroup>
    {state.presentation === "feature" ? <><ControlGroup label="Feature content"><label className="block text-[10px] text-white/58">Title<input value={state.title} onChange={(event) => patch({ ...node.props, videoTitle: event.target.value }, "Changed Video title")} className="mt-1.5 h-10 w-full rounded-lg bg-white/5 px-3" /></label><label className="block text-[10px] text-white/58">Subtitle<input value={state.subtitle || ""} onChange={(event) => patch({ ...node.props, videoSubtitle: event.target.value }, "Changed Video subtitle")} className="mt-1.5 h-10 w-full rounded-lg bg-white/5 px-3" /></label><label className="block text-[10px] text-white/58">Short description<textarea value={state.description || ""} onChange={(event) => patch({ ...node.props, videoDescription: event.target.value }, "Changed Video description")} className="mt-1.5 min-h-20 w-full rounded-lg bg-white/5 p-3" /></label>{([['videoShowTitle','Show title',state.showTitle],['videoShowSubtitle','Show subtitle',state.showSubtitle],['videoShowDescription','Show description',state.showDescription]] as const).map(([key,label,checked]) => <label key={key} className="flex min-h-10 items-center justify-between rounded-xl bg-white/4 px-3 text-[9px]"><span>{label}</span><input type="checkbox" checked={checked} onChange={(event) => patch({ ...node.props, [key]: event.target.checked }, `Changed Video ${label}`)} /></label>)}</ControlGroup><ControlGroup label="Feature frame"><Segmented values={["transparent","solid","glass","artist-surface"]} value={state.frameTreatment} onChange={(value) => patch({ ...node.props, videoFrameTreatment: value }, `Changed Video frame to ${value}`)} label="Treatment" /><ColorInput label="Frame color" value={hex(state.frameColor, "#0b111b")} onChange={(value) => patch({ ...node.props, videoFrameColor: value }, "Changed Video frame color")} /><ColorInput label="Accent" value={hex(state.frameAccent, "#b8ff2c")} onChange={(value) => patch({ ...node.props, videoFrameAccent: value }, "Changed Video accent")} /><Segmented values={["circle","minimal","accent"]} value={state.playPresentation} onChange={(value) => patch({ ...node.props, videoPlayPresentation: value }, `Changed Video Play treatment to ${value}`)} label="Play affordance" /><StudioPrecisionControl label="Corner radius" value={state.frameRadiusPx} descriptor={{ unit: "px", min: 0, max: 64, step: 1, defaultValue: 18 }} onPreview={(value) => model.previewCompositionNode?.(node.id, { props: { ...node.props, videoFrameRadiusPx: value } })} onBegin={model.beginLiveAdjustment} onCommit={() => model.commitLiveAdjustment?.("Changed Video frame radius")} onCancel={model.cancelLiveAdjustment} /></ControlGroup></> : null}
    <ControlGroup label="Access">
      <label className="flex min-h-10 items-center justify-between rounded-xl bg-white/4 px-3 text-[9px]"><span>Locked experience</span><input type="checkbox" checked={state.locked} onChange={(event) => patch({ ...node.props, accessState: event.target.checked ? "locked" : "public", lockedBehavior: event.target.checked ? state.lockedBehavior ?? { mode: "message", message: "This video requires additional access." } : node.props.lockedBehavior }, `${event.target.checked ? "Locked" : "Unlocked"} Video`)} /></label>
      {state.locked ? <>
        <Segmented values={["none","message","cta","hidden"]} value={state.lockedBehavior?.mode || "message"} onChange={(value) => patch({ ...node.props, lockedBehavior: { ...state.lockedBehavior, mode: value } }, `Changed locked Video behavior to ${value}`)} label="When locked" />
        {state.lockedBehavior?.mode === "message" || state.lockedBehavior?.mode === "cta" ? <label className="block text-[10px] text-white/58">Message<input value={state.lockedBehavior?.message || ""} onChange={(event) => patch({ ...node.props, lockedBehavior: { ...state.lockedBehavior, message: event.target.value } }, "Changed locked Video message")} className="mt-1.5 h-10 w-full rounded-lg bg-white/5 px-3" /></label> : null}
        {state.lockedBehavior?.mode === "cta" ? <>
          <label className="block text-[10px] text-white/58">CTA label<input value={state.lockedBehavior?.ctaLabel || ""} onChange={(event) => patch({ ...node.props, lockedBehavior: { ...state.lockedBehavior, ctaLabel: event.target.value } }, "Changed locked Video CTA label")} className="mt-1.5 h-10 w-full rounded-lg bg-white/5 px-3" /></label>
          <Segmented values={["external","internal_page"]} value={state.lockedBehavior?.ctaDestinationType || "external"} onChange={(value) => patch({ ...node.props, lockedBehavior: { ...state.lockedBehavior, ctaDestinationType: value, ctaDestinationRef: "" } }, `Changed locked Video CTA Action to ${value}`)} label="CTA Action" />
          {state.lockedBehavior?.ctaDestinationType === "internal_page" ? <StudioInternalPagePicker pages={model.experiencePages} value={state.lockedBehavior?.ctaDestinationRef || ""} onChange={(pageId) => patch({ ...node.props, lockedBehavior: { ...state.lockedBehavior, ctaDestinationType: "internal_page", ctaDestinationRef: pageId } }, "Mapped locked Video CTA to Experience Page")} testId="studio-video-locked-cta-page" /> : <label className="block text-[10px] text-white/58">CTA destination<input value={state.lockedBehavior?.ctaDestinationRef || ""} onChange={(event) => patch({ ...node.props, lockedBehavior: { ...state.lockedBehavior, ctaDestinationType: "external", ctaDestinationRef: event.target.value } }, "Changed locked Video CTA destination")} className="mt-1.5 h-10 w-full rounded-lg bg-white/5 px-3" /></label>}
        </> : null}
      </> : null}
    </ControlGroup>
    <ControlGroup label="Accessibility & analytics"><label className="block text-[10px] text-white/58">Video title<input value={state.title} onChange={(event) => patch({ ...node.props, videoTitle: event.target.value }, "Changed Video title")} className="mt-1.5 h-10 w-full rounded-lg bg-white/5 px-3" /></label>{state.presentation !== "feature" ? <label className="block text-[10px] text-white/58">Description<textarea value={state.description || ""} onChange={(event) => patch({ ...node.props, videoDescription: event.target.value }, "Changed Video description")} className="mt-1.5 min-h-20 w-full rounded-lg bg-white/5 p-3" /></label> : null}<label className="block text-[10px] text-white/58">Captions URL<input type="url" value={state.captionsUrl || ""} onChange={(event) => patch({ ...node.props, captionsUrl: event.target.value }, "Changed Video captions")} className="mt-1.5 h-10 w-full rounded-lg bg-white/5 px-3" /></label><label className="block text-[10px] text-white/58">Component analytics identity<input value={state.analyticsId || ""} onChange={(event) => patch({ ...node.props, analyticsId: event.target.value }, "Changed Video analytics identity")} className="mt-1.5 h-10 w-full rounded-lg bg-white/5 px-3" /></label><p className="text-[9px] leading-4 text-white/38">The platform derives impression, play, pause, completion, CTA, and locked-attempt event types from this stable component identity; Hosts do not author event names.</p></ControlGroup>
  </div>;
}

function LayeredPositionControls({ node, model, block }: { node: CreativeCompositionNode; model: CardEditorLiveModel; block: NonNullable<CardEditorLiveModel["config"]["rootComposition"]> }) {
  const patch = (next: Partial<CreativeCompositionNode>, label: string) => model.patchCompositionNode(node.id, next, label);
  const resizePolicy = layeredResizePolicy(node);
  const z = (command: LayeredZCommand, label: string) => model.patchConfig({ rootComposition: reorderLayeredNodeZ(block, node.id, command) }, label);
  return <ControlGroup label="Position · Local layer"><p className="text-[9px] leading-4 text-[#a9e7ff]/70">Bounded by {node.parentId ? "its Container" : "Card Surface"}. Drag on canvas or use exact responsive geometry.</p>{resizePolicy === "governed-aspect" ? <p className="rounded-lg bg-[#b8ff2c]/8 p-2 text-[9px] leading-4 text-[#d8ff82]/75">Curated proportions are governed. Resize from the canvas handle or choose a certified size preset.</p> : null}<div className="grid grid-cols-2 gap-2">{([['x','X'],['y','Y'],['width','Width'],['height','Height']] as const).map(([key,label]) => { const disabled = resizePolicy === "governed-aspect" && (key === "width" || key === "height") || resizePolicy === "width-only" && key === "height"; return <label key={key} className="text-[9px] text-white/48">{label}<input type="number" min={0} max={100} value={Math.round(node[key] * 100)} disabled={disabled} onChange={(event) => patch({ [key]: Math.max(0, Math.min(1, Number(event.target.value) / 100)) }, `Changed layered Module ${label}`)} className="mt-1 h-9 w-full rounded-lg bg-white/5 px-2 disabled:cursor-not-allowed disabled:opacity-35" data-testid={`studio-layered-${key}`} /></label>; })}</div><p className="text-[9px] text-white/42">Anchor</p><div className="grid grid-cols-3 gap-1">{(["top-left","top","top-right","left","center","right","bottom-left","bottom","bottom-right"] as const).map((anchor) => <button key={anchor} type="button" title={anchor} aria-label={`Anchor ${anchor}`} aria-pressed={(node.anchor || "top-left") === anchor} onClick={() => patch({ anchor }, `Changed layered Module anchor to ${anchor}`)} className="min-h-8 rounded-lg bg-white/5 text-[8px] aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]">{anchor.replace("-", " ")}</button>)}</div><div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => z("back", "Sent layered Module to back")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Send to back</button><button type="button" onClick={() => z("backward", "Sent layered Module backward")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Send backward</button><button type="button" onClick={() => z("forward", "Brought layered Module forward")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Bring forward</button><button type="button" onClick={() => z("front", "Brought layered Module to front")} className="min-h-10 rounded-xl border border-white/10 text-[10px]">Bring to front</button></div><div className="grid grid-cols-2 gap-2"><label className="flex min-h-10 items-center justify-between rounded-xl bg-white/4 px-3 text-[9px]"><span>Lock</span><input type="checkbox" checked={node.locked === true} onChange={(event) => patch({ locked: event.target.checked }, `${event.target.checked ? "Locked" : "Unlocked"} layered Module`)} /></label><label className="flex min-h-10 items-center justify-between rounded-xl bg-white/4 px-3 text-[9px]"><span>Visible</span><input type="checkbox" checked={node.visible !== false} onChange={(event) => patch({ visible: event.target.checked }, `${event.target.checked ? "Showed" : "Hid"} layered Module`)} /></label></div></ControlGroup>;
}

function TextControls({ node, model, block, brand }: { node: CreativeCompositionNode; model: CardEditorLiveModel; block: NonNullable<CardEditorLiveModel["config"]["rootComposition"]>; brand: BrandPreviewContext }) {
  const [fontQuery, setFontQuery] = useState("");
  const [fontBrowserOpen, setFontBrowserOpen] = useState(false);
  const [recentFontIds, setRecentFontIds] = useState<string[]>([]);
  const accessibility = evaluateStudioTextAccessibility(node, block, model.config.surfaceColor || brand.backgroundColor);
  const role = studioTextRole(node.props.textRole);
  const brandColors = [...new Set([brand.textColor, brand.primaryColor, brand.secondaryColor, brand.accentColor].filter((value): value is string => Boolean(value && /^#[0-9a-f]{6}$/i.test(value))))];
  const patch = (values: Record<string, unknown>, label: string) => model.patchCompositionNode(node.id, { props: { ...node.props, ...values } }, label);
  const preview = (values: Record<string, unknown>) => model.previewCompositionNode?.(node.id, { props: { ...node.props, ...values } });
  const precision = (label: string) => ({ onBegin: model.beginLiveAdjustment, onCommit: () => model.commitLiveAdjustment?.(label), onCancel: model.cancelLiveAdjustment });
  const brandDefaults = textRoleCanonicalProps(role.id, brand);
  const fonts = useMemo(() => {
    const matching = searchFonts(fontQuery);
    if (fontQuery.trim()) return matching.slice(0, 18);
    const recent = recentFontIds.flatMap((id) => FONT_CATALOG.find((font) => font.id === id) ?? []);
    const recommended = FONT_CATALOG.filter((font) => ["inter", "manrope", "playfair", "source-serif-4", "space-grotesk", "lexend"].includes(font.id));
    return [...new Map([...recent, ...recommended].map((font) => [font.id, font])).values()].slice(0, 10);
  }, [fontQuery, recentFontIds]);

  useEffect(() => {
    if (!fontBrowserOpen) return;
    let active = true;
    void fetch("/api/studio/activity?consumer=card-composer&context=text-font&resourceKind=font&limit=8")
      .then((response) => response.ok ? response.json() : Promise.reject())
      .then((payload: { recents?: Array<{ resource?: { provider?: string; resourceId?: string } }> }) => {
        if (!active) return;
        setRecentFontIds((payload.recents ?? []).flatMap((recent) => recent.resource?.provider === "tapconnect-text" && recent.resource.resourceId?.startsWith("font:") ? [recent.resource.resourceId.slice(5)] : []));
      }).catch(() => undefined);
    return () => { active = false; };
  }, [fontBrowserOpen]);

  const applyFont = (fontId: string) => {
    const font = FONT_CATALOG.find((candidate) => candidate.id === fontId);
    if (!font) return;
    void ensureFontLoaded(font.id).catch(() => model.notify?.(`${font.family} could not be loaded; showing its safe fallback.`));
    patch({ fontFamily: fontCssStack(font), fontSource: "local", textStyleSource: "local" }, `Changed Text typeface to ${font.family}`);
    setRecentFontIds((current) => [font.id, ...current.filter((id) => id !== font.id)].slice(0, 8));
    void fetch("/api/studio/activity", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ resource: { provider: "tapconnect-text", resourceId: `font:${font.id}`, version: 1 }, resourceKind: "font", consumer: "card-composer", context: "text-font", operation: "apply" }) }).catch(() => undefined);
    setFontBrowserOpen(false);
  };

  return <div data-text-authoring-contract={STUDIO_TEXT_AUTHORING_CONTRACT}>
    <ControlGroup label="Content"><TransactionalTextArea node={node} model={model} /></ControlGroup>
    <ControlGroup label="Role"><div className="grid grid-cols-2 gap-2">{STUDIO_TEXT_ROLES.map((candidate) => <button key={candidate.id} type="button" aria-pressed={role.id === candidate.id} onClick={() => model.patchCompositionNode(node.id, { props: applyStudioTextRole(node.props, candidate.id, brand) }, `Changed Text role to ${candidate.label}`)} className="min-h-14 rounded-xl bg-white/5 px-3 text-left aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]" data-testid={`studio-text-role-${candidate.id}`}><strong className="block text-[11px]">{candidate.label}</strong><span className="mt-0.5 block text-[8px] opacity-60">{candidate.description}</span></button>)}</div></ControlGroup>
    <ControlGroup label="Typeface"><div className="rounded-xl bg-white/4 p-3"><div className="flex items-center justify-between gap-3"><div className="min-w-0"><p className="truncate text-sm" style={{ fontFamily: String(node.props.fontFamily) }}>{String(node.props.fontFamily || "Inter").split(",")[0].replaceAll('"', "")}</p><p className="mt-0.5 text-[9px] text-white/38">{node.props.fontSource === "local" ? "Custom on this Text" : "From Brand"}</p></div><button type="button" onClick={() => setFontBrowserOpen((open) => !open)} className="min-h-9 rounded-lg border border-white/10 px-3 text-[10px]" data-testid="studio-text-font-browser">Browse fonts</button></div>{node.props.fontSource === "local" ? <button type="button" onClick={() => patch({ fontFamily: brandDefaults.fontFamily, fontSource: "brand" }, "Reset Text typeface to Brand")} className="mt-2 text-[9px] font-semibold text-[#b8ff2c]">Reset to Brand typeface</button> : null}</div>{fontBrowserOpen ? <div className="mt-3 rounded-2xl border border-white/10 bg-[#080d14] p-2" data-testid="studio-font-browser"><label className="flex items-center gap-2 rounded-xl bg-white/5 px-3"><Search className="h-3.5 w-3.5 text-white/36" /><input value={fontQuery} onChange={(event) => setFontQuery(event.target.value)} placeholder="Search open-source fonts" className="h-10 min-w-0 flex-1 bg-transparent text-xs outline-none" /></label><p className="px-1 pb-1 pt-3 text-[9px] uppercase tracking-[.12em] text-white/35">{fontQuery ? "Results" : recentFontIds.length ? "Recent and recommended" : "Recommended"}</p><div className="max-h-56 space-y-1 overflow-y-auto">{fonts.map((font) => <button key={font.id} type="button" onMouseEnter={() => void ensureFontLoaded(font.id).catch(() => undefined)} onClick={() => applyFont(font.id)} className="flex min-h-11 w-full items-center rounded-lg px-3 text-left hover:bg-white/7"><span className="flex-1 text-base" style={{ fontFamily: fontCssStack(font) }}>{font.family}</span><span className="text-[8px] text-white/30">{font.category}</span></button>)}</div></div> : null}</ControlGroup>
    <ControlGroup label="Typography"><StudioPrecisionControl label="Size" value={Number(node.props.fontSize ?? 18)} descriptor={{ unit: "px", min: 10, max: 96, step: 1, fineStep: .5, defaultValue: Number(role.defaults.fontSize) }} onPreview={(value) => preview({ fontSize: value, textStyleSource: "local" })} {...precision("Changed Text size")} /><StudioPrecisionControl label="Weight" value={Number(node.props.fontWeight ?? 600)} descriptor={{ unit: "number", min: 300, max: 900, step: 50, defaultValue: Number(role.defaults.fontWeight) }} onPreview={(value) => preview({ fontWeight: value, textStyleSource: "local" })} {...precision("Changed Text weight")} /><StudioPrecisionControl label="Line height" value={Number(node.props.lineHeight ?? 1.2)} descriptor={{ unit: "number", min: .8, max: 2.4, step: .05, fineStep: .01, defaultValue: Number(role.defaults.lineHeight) }} onPreview={(value) => preview({ lineHeight: value, textStyleSource: "local" })} {...precision("Changed Text line height")} /><StudioPrecisionControl label="Letter spacing" value={Number(node.props.letterSpacingEm ?? 0)} descriptor={{ unit: "number", min: -.08, max: .3, step: .01, fineStep: .005, defaultValue: Number(role.defaults.letterSpacingEm) }} onPreview={(value) => preview({ letterSpacingEm: value, textStyleSource: "local" })} {...precision("Changed Text letter spacing")} /><Segmented values={["left","center","right"]} value={String(node.props.align || "left")} onChange={(value) => patch({ align: value, textStyleSource: "local" }, `Aligned Text ${value}`)} label="Alignment" /></ControlGroup>
    <ControlGroup label="Color"><p className="text-[9px] text-white/40">{node.props.colorSource === "local" ? "Custom on this Text" : "From Brand"}</p><ColorInput label="Text color" value={hex(node.props.color, "#f8fafc")} onChange={(value) => patch({ color: value, colorSource: "local" }, "Changed Text color")} />{brandColors.length ? <div className="flex gap-2" aria-label="Brand colors">{brandColors.map((value) => <button key={value} type="button" onClick={() => patch({ color: value, colorSource: "brand" }, "Applied Brand color to Text")} className="h-9 w-9 rounded-full border border-white/20" style={{ background: value }} aria-label={`Use Brand color ${value}`} />)}</div> : null}{node.props.colorSource === "local" ? <button type="button" onClick={() => patch({ color: brandDefaults.color, colorSource: "brand" }, "Reset Text color to Brand")} className="text-[9px] font-semibold text-[#b8ff2c]">Reset to Brand color</button> : null}</ControlGroup>
    <ControlGroup label="Text Box"><p className="text-[9px] leading-4 text-white/42">The box surface stays independent from editable glyphs and uses the same canonical Text renderer in Studio, Preview, Live Device, and public Card.</p><Segmented values={["transparent","filled","outlined"]} value={node.props.boxGradient || String(node.props.boxFill || "transparent") !== "transparent" ? "filled" : Number(node.props.boxBorderWidth ?? 0) > 0 ? "outlined" : "transparent"} onChange={(value) => value === "transparent" ? patch({ boxFill: "transparent", boxGradient: undefined, boxBorderWidth: 0 }, "Made Text Box transparent") : value === "filled" ? patch({ boxFill: hex(node.props.boxFill, "#111827"), boxFillOpacity: Number(node.props.boxFillOpacity ?? .72) }, "Added Text Box fill") : patch({ boxFill: "transparent", boxGradient: undefined, boxBorder: hex(node.props.boxBorder, "#ffffff"), boxBorderWidth: Math.max(1, Number(node.props.boxBorderWidth ?? 1)) }, "Outlined Text Box")} label="Surface" />{String(node.props.boxFill || "transparent") !== "transparent" || node.props.boxGradient ? <><ColorInput label="Box fill" value={hex(node.props.boxFill, "#111827")} onChange={(value) => patch({ boxFill: value, boxGradient: undefined }, "Changed Text Box fill")} /><StudioPrecisionControl label="Fill opacity" value={Number(node.props.boxFillOpacity ?? 1)} descriptor={{ unit: "number", min: 0, max: 1, step: .05, fineStep: .01, defaultValue: 1 }} onPreview={(value) => preview({ boxFillOpacity: value })} {...precision("Changed Text Box fill opacity")} /></> : null}<ColorInput label="Border color" value={hex(node.props.boxBorder, "#ffffff")} onChange={(value) => patch({ boxBorder: value, boxBorderWidth: Math.max(1, Number(node.props.boxBorderWidth ?? 1)) }, "Changed Text Box border color")} /><StudioPrecisionControl label="Border width" value={Number(node.props.boxBorderWidth ?? 0)} descriptor={{ unit: "px", min: 0, max: 12, step: 1, fineStep: .5, defaultValue: 0 }} onPreview={(value) => preview({ boxBorderWidth: value })} {...precision("Changed Text Box border width")} /><StudioPrecisionControl label="Corner radius" value={Number(node.props.boxRadius ?? 0)} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 0 }} onPreview={(value) => preview({ boxRadius: value })} {...precision("Changed Text Box corner radius")} /><StudioPrecisionControl label="Padding" value={Number(node.props.boxPadding ?? 0)} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 0 }} onPreview={(value) => preview({ boxPadding: value })} {...precision("Changed Text Box padding")} /><StudioPrecisionControl label="Shadow" value={Number(node.props.boxShadow ?? 0)} descriptor={{ unit: "px", min: 0, max: 64, step: 1, fineStep: .5, defaultValue: 0 }} onPreview={(value) => preview({ boxShadow: value })} {...precision("Changed Text Box shadow")} /><StudioPrecisionControl label="Overall opacity" value={Number(node.props.opacity ?? 1)} descriptor={{ unit: "number", min: 0, max: 1, step: .05, fineStep: .01, defaultValue: 1 }} onPreview={(value) => preview({ opacity: value })} {...precision("Changed Text Box opacity")} /></ControlGroup>
    <ControlGroup label="Text Box height"><Segmented values={["auto","minimum","fixed"]} value={String(node.props.textHeightMode || "auto")} onChange={(value) => patch({ textHeightMode: value, textOverflow: value === "fixed" ? String(node.props.textOverflow || "visible") : "visible", ...(value === "fixed" ? { textFixedHeightPx: Math.max(Number(node.props.textMinHeightPx ?? role.minHeightPx), Number(node.props.textFixedHeightPx ?? node.props.textMinHeightPx ?? role.minHeightPx)) } : {}) }, `Changed Text Box height mode to ${value}`)} label="Height behavior" /><p className="text-[9px] leading-4 text-white/40">Auto grows with content. Minimum grows but never below the authored minimum. Fixed uses an explicit height and overflow choice.</p>{String(node.props.textHeightMode || "auto") === "minimum" ? <StudioPrecisionControl label="Minimum height" value={Number(node.props.textMinHeightPx ?? role.minHeightPx)} descriptor={{ unit: "px", min: 24, max: 640, step: 1, defaultValue: role.minHeightPx }} onPreview={(value) => preview({ textMinHeightPx: value })} {...precision("Changed Text Box minimum height")} /> : null}{String(node.props.textHeightMode || "auto") === "fixed" ? <><StudioPrecisionControl label="Fixed height" value={Number(node.props.textFixedHeightPx ?? node.props.textMinHeightPx ?? role.minHeightPx)} descriptor={{ unit: "px", min: 24, max: 640, step: 1, defaultValue: role.minHeightPx }} onPreview={(value) => preview({ textFixedHeightPx: value, textMinHeightPx: Math.min(Number(node.props.textMinHeightPx ?? role.minHeightPx), value) })} {...precision("Changed Text Box fixed height")} /><Segmented values={["visible","scroll","clip"]} value={String(node.props.textOverflow || "visible")} onChange={(value) => patch({ textOverflow: value }, `Changed Text Box overflow to ${value}`)} label="Overflow" />{String(node.props.textOverflow || "visible") === "clip" ? <p className="rounded-xl bg-amber-200/8 p-2 text-[9px] leading-4 text-amber-100/75">Clip is explicit and may hide content. Preview before publishing.</p> : null}</> : null}</ControlGroup>
    <ControlGroup label="Accessibility"><div className="space-y-2 text-[10px]"><StatusLine label="Content" status={accessibility.empty ? "warning" : "pass"} detail={accessibility.empty ? "Empty" : "Present"} /><StatusLine label="Phone readability" status={accessibility.phoneReadability} detail={accessibility.phoneReadability === "pass" ? "Comfortable size" : "Under 14 px"} /><StatusLine label="Contrast" status={accessibility.contrast} detail={accessibility.message} /></div></ControlGroup>
  </div>;
}

function TransactionalTextArea({ node, model }: { node: CreativeCompositionNode; model: CardEditorLiveModel }) {
  const canonical = String(node.props.text || "");
  return <label className="block text-[10px] text-white/58">Text<textarea value={canonical} onFocus={() => model.beginLiveAdjustment?.()} onChange={(event) => model.previewCompositionNode?.(node.id, { props: { ...node.props, text: event.target.value } })} onBlur={() => model.commitLiveAdjustment?.("Edited Text content")} onKeyDown={(event) => { if (event.nativeEvent.isComposing) return; if (event.key === "Escape") { event.preventDefault(); model.cancelLiveAdjustment?.(); event.currentTarget.blur(); } else if (event.key === "Enter" && node.props.textMultiline === false) { event.preventDefault(); event.currentTarget.blur(); } }} className="mt-2 min-h-28 w-full resize-y rounded-xl border border-white/10 bg-white/5 p-3 text-sm normal-case tracking-normal text-white outline-none focus:border-[#b8ff2c]" data-studio-keyboard-owner="text-entry" data-testid="studio-text-content" /></label>;
}

function StatusLine({ label, status, detail }: { label: string; status: "pass" | "warning" | "unknown"; detail: string }) {
  return <div className="rounded-xl bg-white/4 px-3 py-2"><div className="flex items-center justify-between gap-2"><span>{label}</span><strong className={status === "pass" ? "text-[#b8ff2c]" : status === "warning" ? "text-amber-200" : "text-white/42"}>{status === "pass" ? "Pass" : status === "warning" ? "Review" : "Check in Preview"}</strong></div><p className="mt-1 leading-4 text-white/38">{detail}</p></div>;
}

function ControlGroup({ label, children }: { label: string; children: ReactNode }) {
  return <section className="mb-6 border-t border-white/8 pt-4" data-control-group={label.toLowerCase().replaceAll(" ", "-")}><p className="mb-3 text-[10px] font-semibold uppercase tracking-[.14em] text-[#a9e7ff]/70">{label}</p><div className="space-y-3">{children}</div></section>;
}

function Segmented({ values, value, onChange, label }: { values: readonly string[]; value: string; onChange: (value: string) => void; label: string }) {
  return <div><p className="mb-1.5 text-[9px] text-white/48">{label}</p><div className={`grid gap-1 ${values.length === 3 ? "grid-cols-3" : "grid-cols-4"}`}>{values.map((item) => <button key={item} type="button" aria-pressed={value === item} onClick={() => onChange(item)} className="min-h-9 rounded-lg bg-white/5 px-1 text-[9px] capitalize aria-pressed:bg-[#b8ff2c] aria-pressed:text-[#07100a]">{item.replaceAll("_", " ")}</button>)}</div></div>;
}

function ColorInput({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) {
  return <StudioColorControl label={label} value={value} source="custom" resetValue={label.toLowerCase().includes("border") ? "#FFFFFF" : "#000000"} onChange={(next) => onChange(next)} />;
}

function hex(value: unknown, fallback: string) { const candidate = String(value || ""); return /^#[0-9a-f]{6}$/i.test(candidate) ? candidate : fallback; }
